"""The 50 test cases: document parameters plus expected results.

Expected-result fields:
  band        expected risk band (Low / Medium / High)
  must_catch  findings the tool must produce: check, severity, clause, quote (verbatim text in the document), why
  must_not    things the tool must NOT do
  acceptable  findings that are fine either way (not scored)
"""
from templates import law_us, money

IN_DESC = 'a company incorporated under the Companies Act, 2013, having its registered office at {}'


def india(addr):
    return IN_DESC.format(addr)


CASES = []


def add(**kw):
    CASES.append(kw)


